/* Decode the request of n bytes at req, which came on ch, call its handler,
 * encode the reply into rep (NSCHAN_REP_MAX bytes) and the handles it carries
 * into rhs (NSCHAN_REP_HANDLES slots; *rhn of them). Returns the reply's
 * length: 0 means no reply (the message has no txid, a `later` handler
 * answers it itself, or it is an event: txid 0, never answered; one no
 * handler takes is dropped). No I/O; the caller sends the reply with the
 * handles, or closes them if it never sends it.
 * The idl_nh handles at idl_hs (an event's, or a call's arguments) are taken
 * in every case: given to the handler, or closed. */
static inline uint32_t nschan_dispatch_h(handle_t ch, const struct nschan_ops *ops, void *ctx,
                                         const void *req, uint32_t n, const handle_t *idl_hs, uint32_t idl_nh,
                                         void *rep, handle_t *rhs, uint32_t *rhn)
{
    struct idl_rep_hdr *idl_h = (struct idl_rep_hdr *)rep;
    *rhn = 0;
    (void)rhs;
    (void)ch;
    if (n < sizeof(struct idl_req_hdr) || !((const struct idl_req_hdr *)req)->txid) {
        /* txid 0: an event (or no txid): never answered */
        if (n >= sizeof(struct idl_req_hdr))
            (void)nschan_event_in(ops, ctx, req, n, idl_hs, idl_nh);
        else
            idl_close_all(idl_hs, idl_nh);
        return 0;
    }
    if (idl_nh) {   /* a request with handles: only an event takes any */
        idl_close_all(idl_hs, idl_nh);
        idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
        idl_h->status = ERR_INVALID_ARGS;
        return sizeof(*idl_h);
    }
    idl_h->txid = ((const struct idl_req_hdr *)req)->txid;
    idl_h->status = ERR_INVALID_ARGS;
    switch (((const struct idl_req_hdr *)req)->ordinal) {
    case NSCHAN_MOUNT:
    case NSCHAN_UNMOUNT:
    case NSCHAN_SET:
        return sizeof(*idl_h);   /* an event with a txid */
    }
    idl_h->status = ERR_NOT_SUPPORTED;
    return sizeof(*idl_h);
}

/* nschan_dispatch_h without handles (a loop of your own that reads none:
 * an event or call that takes some is then refused). */
static inline uint32_t nschan_dispatch_on(handle_t ch, const struct nschan_ops *ops, void *ctx,
                                          const void *req, uint32_t n, void *rep, handle_t *rhs,
                                          uint32_t *rhn)
{
    return nschan_dispatch_h(ch, ops, ctx, req, n, NULL, 0, rep, rhs, rhn);
}

/* nschan_dispatch_on without the channel (the protocol has no `later` method). */
static inline uint32_t nschan_dispatch(const struct nschan_ops *ops, void *ctx, const void *req, uint32_t n,
                                       void *rep, handle_t *rhs, uint32_t *rhn)
{
    return nschan_dispatch_on(HANDLE_INVALID, ops, ctx, req, n, rep, rhs, rhn);
}

/* The unread bound (tools/genidl.py): has ch's client left NSCHAN_UNREAD_MSGS
 * messages or NSCHAN_UNREAD_BYTES bytes of ours unread? Then a loop of the
 * server's own reads nothing more from ch for now: it leaves ch unserved
 * and looks again later (struct idl_held). */
static inline bool nschan_unread_full(handle_t ch)
{
    return idl_unread_full(ch, NSCHAN_UNREAD_MSGS, NSCHAN_UNREAD_BYTES);
}

/* Take the next message on ch into slot (idl_take), a slot with room for
 * the protocol's biggest request (ERR_INVALID_ARGS if it has less). The
 * reply waiting in *rep (NULL or empty: none) goes out first in the same
 * system call (idl_take_after). It never waits: ERR_SHOULD_WAIT when
 * nothing is queued. */
static inline status_t nschan_take_slot(handle_t ch, const struct idl_slot *slot,
                                        struct idl_reply *rep)
{
    if (slot->qcap < NSCHAN_REQ_MAX)
        return ERR_INVALID_ARGS;
    if (rep && rep->ch != HANDLE_INVALID)
        return idl_take_after(ch, slot, rep);
    return idl_take(ch, slot);
}

/* Run the message in slot (taken by nschan_take_slot, or found there by a
 * successor), which came on ch: as nschan_dispatch_h, its reply built in
 * slot->r and the handles that reply carries put into rhs
 * (NSCHAN_REP_HANDLES slots; *rhn of them). The handles it carried
 * (*slot->nh in slot->hs) are taken: given to a handler or closed,
 * *slot->nh 0 after. Returns the reply's length: 0 means no reply
 * (no txid, an event, or a `later` handler answers it itself). No I/O;
 * the caller sends the reply with the handles, or closes them if it
 * never sends it. */
static inline uint32_t nschan_run_slot(handle_t ch, const struct idl_slot *slot,
                                       const struct nschan_ops *ops, void *ctx, handle_t *rhs, uint32_t *rhn)
{
    uint32_t idl_nh = *slot->nh;
    *slot->nh = 0;
    return nschan_dispatch_h(ch, ops, ctx, slot->q, *slot->n, slot->hs, idl_nh, slot->r,
                          rhs, rhn);
}

/* Is the method with this wire ordinal idempotent (its keyword in the
 * .idl): run again on the state its first run left, it gives the same
 * result and the same answer? A server that keeps nothing across a
 * restart may run such a request again; any other it answers with an
 * error. (No server reads it yet: it is for the drivers that outlive
 * their process, after M12.) */
static inline bool nschan_idempotent(uint32_t ordinal)
{
    (void)ordinal;
    return false;   /* no method is marked */
}

/* Take one message off ch and answer it (the unread bound is the caller's:
 * nschan_unread_full first). OK once a message was handled
 * (its reply may still have been dropped: the client is gone, or never
 * called); otherwise drv_channel_read's status: ERR_SHOULD_WAIT when
 * nothing is queued, ERR_PEER_CLOSED when the client is gone for good. */
static inline status_t nschan_serve_one(handle_t ch, const struct nschan_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[NSCHAN_REQ_MAX];
    _Alignas(8) uint8_t idl_r[NSCHAN_REP_MAX];
    handle_t idl_hs[NSCHAN_REQ_HANDLES];
    uint32_t idl_n = 0, idl_nh = 0;
    status_t idl_st = drv_channel_read(ch, idl_q, NSCHAN_REQ_MAX, &idl_n, idl_hs, NSCHAN_REQ_HANDLES,
                                       &idl_nh);
    if (idl_st == ERR_BUFFER_TOO_SMALL) {
        idl_st = idl_drain(ch, idl_n, idl_nh);
    } else if (idl_st == OK) {
        handle_t idl_rhs[IDL_REP_HANDLES];
        uint32_t idl_rhn = 0;
        uint32_t idl_rn = nschan_dispatch_h(ch, ops, ctx, idl_q, idl_n, idl_hs, idl_nh, idl_r,
                                         idl_rhs, &idl_rhn);
        if (!idl_rn)
            idl_close_all(idl_rhs, idl_rhn);   /* no reply: never sent */
        else   /* the reply's handles are gone whatever the write's status */
            (void)drv_channel_write(ch, idl_r, idl_rn, idl_rhs, idl_rhn);
    }
    return idl_st;
}

/* Serve ch until the client closes it (OK), or a wait or read fails
 * (that status: ERR_CANCELED when the driver is being killed). Each reply
 * goes out in the system call that takes the next request, and a client
 * with NSCHAN_UNREAD_MSGS answers unread waits until it reads (idl_serve_next). */
static inline status_t nschan_serve(handle_t ch, const struct nschan_ops *ops, void *ctx)
{
    _Alignas(8) uint8_t idl_q[NSCHAN_REQ_MAX];
    _Alignas(8) uint8_t idl_r[NSCHAN_REP_MAX];
    handle_t idl_rhs[IDL_REP_HANDLES], idl_hs[NSCHAN_REQ_HANDLES];
    struct idl_serve idl_s = {
        .ch = ch, .q = idl_q, .qcap = NSCHAN_REQ_MAX, .r = idl_r, .rhs = idl_rhs,
        .hs = idl_hs, .hcap = NSCHAN_REQ_HANDLES,
        .umsgs = NSCHAN_UNREAD_MSGS, .ubytes = NSCHAN_UNREAD_BYTES,
    };
    status_t idl_st;
    while ((idl_st = idl_serve_next(&idl_s)) == OK)
        idl_s.rn = nschan_dispatch_h(ch, ops, ctx, idl_q, idl_s.n, idl_hs, idl_s.nh, idl_r,
                                  idl_rhs, &idl_s.rhn);
    return idl_st == ERR_PEER_CLOSED ? OK : idl_st;
}
